div.script:
// Wait for jQuery to be available
(function() {
    function initPurchaseRequestPortal() {
        if (typeof jQuery === 'undefined') {
            // jQuery not loaded yet, wait and try again
            setTimeout(initPurchaseRequestPortal, 50);
            return;
        }

        // jQuery is available, use it
        jQuery(document).ready(function($) {
            'use strict';

            console.log('Purchase Request Portal - JavaScript Loaded');

            var lineCounter = 0;

            // Function to add a new line
            function addLine() {
                var lineIndex = lineCounter;
                lineCounter++;

                // Get UOM options from template
                var uomOptions = $('#uom_template').html() || '';

                // Use template literals to avoid XML escaping issues
                var lineHtml = `
                    <div class="card mb-3 request-line-item">
                        <div class="card-body">
                            <div class="row">
                                <div class="col-md-5">
                                    <div class="form-group">
                                        <label for="line_name_${lineIndex}">Producto/Descripcion <span class="text-danger">*</span></label>
                                        <input type="text" name="line_name_${lineIndex}" id="line_name_${lineIndex}" class="form-control" required="required" placeholder="Ingresa la descripcion o el producto a solicitar"/>
                                    </div>
                                </div>
                                <div class="col-md-3">
                                    <div class="form-group">
                                        <label for="line_qty_${lineIndex}">Cantidad <span class="text-danger">*</span></label>
                                        <input type="number" name="line_qty_${lineIndex}" id="line_qty_${lineIndex}" class="form-control" required="required" min="0.01" step="0.01" value="1.00"/>
                                    </div>
                                </div>
                                <div class="col-md-3">
                                    <div class="form-group">
                                        <label for="line_uom_${lineIndex}">Unidad <span class="text-danger">*</span></label>
                                        <select name="line_uom_${lineIndex}" id="line_uom_${lineIndex}" class="form-control uom-select" required="required">
                                            ${uomOptions}
                                        </select>
                                    </div>
                                </div>
                                <div class="col-md-1 d-flex align-items-center">
                                    <button type="button" class="btn btn-danger btn-sm remove_line_btn mt-3">
                                        <i class="fa fa-trash"></i>
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                `;

                $('#request_lines_container').append(lineHtml);
                console.log('Line added, total lines:', lineCounter);
            }

            // Function to validate form before submission
            function validateForm() {
                console.log('=== Form Submission Validation ===');

                // Get all line inputs
                var lineInputs = $('input[name^="line_name_"]');
                console.log('Total line name inputs found:', lineInputs.length);

                // Log each line
                lineInputs.each(function(index, input) {
                    var name = $(input).attr('name');
                    var value = $(input).val();
                    console.log('Line input:', name, '=', value);
                });

                // Check if we have at least one line with data
                var hasValidLine = false;
                lineInputs.each(function(index, input) {
                    if ($(input).val().trim() !== '') {
                        hasValidLine = true;
                    }
                });

                if (!hasValidLine) {
                    alert('Please add at least one product line!');
                    console.error('No valid lines found!');
                    return false;
                }

                console.log('Form validation passed, submitting...');
                return true;
            }

            // Function to handle department change - filter employees based on data attribute
            function onDepartmentChange() {
                var departmentId = $('#department_id').val();
                var $employeeSelect = $('#employee_id');

                if (!departmentId) {
                    // If no department selected, hide all employees
                    $employeeSelect.find('option').each(function() {
                        if ($(this).val() !== '') {
                            $(this).hide();
                        }
                    });
                    $employeeSelect.val('');
                    return;
                }

                // Loop through each option in the employee select
                $employeeSelect.find('option').each(function() {
                    var $option = $(this);

                    // Skip the placeholder option
                    if ($option.val() === '') {
                        $option.show();
                        return;
                    }

                    // Get the department ID of the employee option
                    var employeeDepartmentId = $option.attr('data-department-id');

                    // Show or hide the option based on whether it matches the selected department ID
                    if (employeeDepartmentId === departmentId) {
                        $option.show();
                    } else {
                        $option.hide();
                    }
                });

                // Reset the employee select value
                $employeeSelect.val('');

                console.log('Department changed to:', departmentId);
            }

            // Add first line by default
            addLine();

            // Department change handler
            $(document).on('change', '#department_id', onDepartmentChange);

            // Add line button handler
            $(document).on('click', '#add_line_btn', function(e) {
                e.preventDefault();
                addLine();
            });

            // Remove line button handler (using event delegation)
            $(document).on('click', '.remove_line_btn', function(e) {
                e.preventDefault();
                $(this).closest('.request-line-item').remove();
                console.log('Line removed');
            });

            // Run the filter function initially to hide all employees until department is selected
            onDepartmentChange();
        });
    }

    // Start trying to initialize
    initPurchaseRequestPortal();
})();
